// ServerInterface represents all server handlers.
type ServerInterface interface {
	// User login
	// (POST /auth/login)
	LoginUser(ctx echo.Context) error
	// User logout
	// (POST /auth/logout)
	LogoutUser(ctx echo.Context) error
	// Register a new user account
	// (POST /auth/register)
	RegisterUser(ctx echo.Context) error
	// List personal access tokens
	// (GET /auth/tokens)
	ListTokens(ctx echo.Context) error
	// Create a personal access token
	// (POST /auth/tokens)
	CreateToken(ctx echo.Context) error
	// Revoke a personal access token
	// (DELETE /auth/tokens/{id})
	RevokeToken(ctx echo.Context, id IdPathParam) error
	// List user budgets
	// (GET /budgets)
	ListBudgets(ctx echo.Context) error
	// Create a new budget
	// (POST /budgets)
	CreateBudget(ctx echo.Context) error
	// Update budget settings (OWNER required)
	// (PATCH /budgets/{budgetId})
	UpdateBudget(ctx echo.Context, budgetId BudgetIdPathParam) error
	// List budget accounts
	// (GET /budgets/{budgetId}/accounts)
	ListAccounts(ctx echo.Context, budgetId BudgetIdPathParam) error
	// Create a budget account
	// (POST /budgets/{budgetId}/accounts)
	CreateAccount(ctx echo.Context, budgetId BudgetIdPathParam) error
	// Import CSV bank statement into account (EDITOR+ required)
	// (POST /budgets/{budgetId}/accounts/{accountId}/import-csv)
	ImportAccountCsv(ctx echo.Context, budgetId BudgetIdPathParam, accountId openapi_types.UUID) error
	// List buckets with balances
	// (GET /budgets/{budgetId}/buckets)
	ListBuckets(ctx echo.Context, budgetId BudgetIdPathParam) error
	// Create a bucket
	// (POST /budgets/{budgetId}/buckets)
	CreateBucket(ctx echo.Context, budgetId BudgetIdPathParam) error
	// Create a target in a bucket
	// (POST /budgets/{budgetId}/buckets/{id}/targets)
	CreateTarget(ctx echo.Context, budgetId BudgetIdPathParam, id IdPathParam) error
	// Link bank integration to a budget account (EDITOR+ required)
	// (POST /budgets/{budgetId}/integrations/{integrationId}/link-account)
	LinkIntegrationAccount(ctx echo.Context, budgetId BudgetIdPathParam, integrationId openapi_types.UUID) error
	// Trigger bank integration sync (EDITOR+ required)
	// (POST /budgets/{budgetId}/integrations/{integrationId}/sync)
	SyncIntegration(ctx echo.Context, budgetId BudgetIdPathParam, integrationId openapi_types.UUID) error
	// Invite a user to the budget (ADMIN+ required)
	// (POST /budgets/{budgetId}/invitations)
	InviteBudgetMember(ctx echo.Context, budgetId BudgetIdPathParam) error
	// List matching rules
	// (GET /budgets/{budgetId}/matching-rules)
	ListMatchingRules(ctx echo.Context, budgetId BudgetIdPathParam) error
	// Create a matching rule
	// (POST /budgets/{budgetId}/matching-rules)
	CreateMatchingRule(ctx echo.Context, budgetId BudgetIdPathParam) error
	// List parties in budget
	// (GET /budgets/{budgetId}/parties)
	ListParties(ctx echo.Context, budgetId BudgetIdPathParam) error
	// Create a party
	// (POST /budgets/{budgetId}/parties)
	CreateParty(ctx echo.Context, budgetId BudgetIdPathParam) error
	// Update a party
	// (PUT /budgets/{budgetId}/parties/{id})
	UpdateParty(ctx echo.Context, budgetId BudgetIdPathParam, id IdPathParam) error
	// Query party cashflow
	// (GET /budgets/{budgetId}/parties/{id}/cashflow)
	GetPartyCashflow(ctx echo.Context, budgetId BudgetIdPathParam, id IdPathParam, params GetPartyCashflowParams) error
	// List raw transactions
	// (GET /budgets/{budgetId}/raw-transactions)
	ListRawTransactions(ctx echo.Context, budgetId BudgetIdPathParam, params ListRawTransactionsParams) error
	// Calculate Age of Money report
	// (GET /budgets/{budgetId}/reports/age-of-money)
	GetAgeOfMoneyReport(ctx echo.Context, budgetId BudgetIdPathParam) error
	// Calculate Balance Forecast report
	// (GET /budgets/{budgetId}/reports/balance-forecast)
	GetBalanceForecastReport(ctx echo.Context, budgetId BudgetIdPathParam, params GetBalanceForecastReportParams) error
	// Calculate Budget Analysis execution report
	// (GET /budgets/{budgetId}/reports/budget-analysis)
	GetBudgetAnalysisReport(ctx echo.Context, budgetId BudgetIdPathParam, params GetBudgetAnalysisReportParams) error
	// Calculate Income vs Expense report
	// (GET /budgets/{budgetId}/reports/income-vs-expense)
	GetIncomeVsExpenseReport(ctx echo.Context, budgetId BudgetIdPathParam, params GetIncomeVsExpenseReportParams) error
	// Run Monte Carlo probabilistic retirement simulation
	// (POST /budgets/{budgetId}/reports/monte-carlo/simulate)
	SimulateMonteCarlo(ctx echo.Context, budgetId BudgetIdPathParam) error
	// Calculate Net Worth report
	// (GET /budgets/{budgetId}/reports/net-worth)
	GetNetWorthReport(ctx echo.Context, budgetId BudgetIdPathParam, params GetNetWorthReportParams) error
	// Query aggregated party cashflow
	// (GET /budgets/{budgetId}/reports/party-cashflow)
	GetPartyCashflowReport(ctx echo.Context, budgetId BudgetIdPathParam, params GetPartyCashflowReportParams) error
	// Calculate Sankey flow diagram data
	// (GET /budgets/{budgetId}/reports/sankey)
	GetSankeyReport(ctx echo.Context, budgetId BudgetIdPathParam, params GetSankeyReportParams) error
	// List saved report widgets
	// (GET /budgets/{budgetId}/reports/saved)
	ListSavedReports(ctx echo.Context, budgetId BudgetIdPathParam) error
	// Save a report widget
	// (POST /budgets/{budgetId}/reports/saved)
	CreateSavedReport(ctx echo.Context, budgetId BudgetIdPathParam) error
	// Update a saved report widget
	// (PUT /budgets/{budgetId}/reports/saved/{id})
	UpdateSavedReport(ctx echo.Context, budgetId BudgetIdPathParam, id IdPathParam) error
	// Calculate Spending Breakdown report
	// (GET /budgets/{budgetId}/reports/spending-breakdown)
	GetSpendingBreakdownReport(ctx echo.Context, budgetId BudgetIdPathParam, params GetSpendingBreakdownReportParams) error
	// Calculate Spending Trends report
	// (GET /budgets/{budgetId}/reports/spending-trends)
	GetSpendingTrendsReport(ctx echo.Context, budgetId BudgetIdPathParam, params GetSpendingTrendsReportParams) error
	// Generate Lua formula with AI assistant (EDITOR+ required)
	// (POST /budgets/{budgetId}/targets/generate-formula)
	GenerateFormula(ctx echo.Context, budgetId BudgetIdPathParam) error
	// Validate Lua formula AST and sandbox dry-run (EDITOR+ required)
	// (POST /budgets/{budgetId}/targets/validate-formula)
	ValidateFormula(ctx echo.Context, budgetId BudgetIdPathParam) error
	// Manually fund a target from Ready to Assign
	// (POST /budgets/{budgetId}/targets/{id}/fund)
	FundTarget(ctx echo.Context, budgetId BudgetIdPathParam, id IdPathParam) error
	// List budget transactions
	// (GET /budgets/{budgetId}/transactions)
	ListBudgetTransactions(ctx echo.Context, budgetId BudgetIdPathParam, params ListBudgetTransactionsParams) error
	// Create a direct budget transaction (Cash / non-integrated)
	// (POST /budgets/{budgetId}/transactions)
	CreateBudgetTransaction(ctx echo.Context, budgetId BudgetIdPathParam) error
	// Resolve raw transactions into budget transactions (Move, Merge, Split)
	// (POST /budgets/{budgetId}/transactions/resolve)
	ResolveTransactions(ctx echo.Context, budgetId BudgetIdPathParam) error
	// Get rolling horizon envelope funding view
	// (GET /budgets/{budgetId}/view/horizon)
	GetHorizonView(ctx echo.Context, budgetId BudgetIdPathParam, params GetHorizonViewParams) error
	// Get entity version history (ADMIN+ required)
	// (GET /budgets/{budgetId}/{entityType}/{id}/history)
	GetEntityHistory(ctx echo.Context, budgetId BudgetIdPathParam, entityType GetEntityHistoryParamsEntityType, id IdPathParam) error
	// Restore entity to a previous version (ADMIN+ required)
	// (POST /budgets/{budgetId}/{entityType}/{id}/restore)
	RestoreEntityVersion(ctx echo.Context, budgetId BudgetIdPathParam, entityType RestoreEntityVersionParamsEntityType, id IdPathParam) error
	// Query historical exchange rates
	// (GET /exchange-rates)
	GetExchangeRates(ctx echo.Context, params GetExchangeRatesParams) error
	// Trigger synchronization of central bank exchange rates
	// (POST /exchange-rates/sync)
	SyncExchangeRates(ctx echo.Context) error
	// List supported bank integration providers
	// (GET /integrations/providers)
	ListIntegrationProviders(ctx echo.Context) error
	// OAuth callback handler
	// (GET /integrations/{provider}/callback)
	ProviderCallback(ctx echo.Context, provider string, params ProviderCallbackParams) error
	// Generate OAuth authorization URL and state token
	// (POST /integrations/{provider}/connect)
	ConnectProvider(ctx echo.Context, provider ConnectProviderParamsProvider) error
	// Accept a budget invitation
	// (POST /invitations/{token}/accept)
	AcceptInvitation(ctx echo.Context, token string) error
	// Get current user profile
	// (GET /users/me)
	GetCurrentUser(ctx echo.Context) error
	// Update current user profile
	// (PUT /users/me)
	UpdateCurrentUser(ctx echo.Context) error
}

// ServerInterfaceWrapper converts echo contexts to parameters.
type ServerInterfaceWrapper struct {
	Handler ServerInterface
}

// LoginUser converts echo context to params.
